node -e "
const axios = require('axios').default.create({adapter:'http'});
const http = require('http');
let srv = http.createServer((req,res)=>{ res.setHeader('Content-Type','application/json'); res.end(JSON.stringify({status:'ready'})); });
srv.listen(0, async ()=>{
  let port=srv.address().port;
  let url='http://localhost:'+port;
  try {
    let r1 = await axios({url, method:'get'});
    console.log('default', typeof r1.data, r1.data);
    let r2 = await axios({url, method:'get', responseType:'text'});
    console.log('text', typeof r2.data, r2.data);
    let r3 = await axios({url, method:'get', responseType:'arraybuffer'});
    console.log('arraybuffer', typeof r3.data, r3.data, Buffer.isBuffer(r3.data));
  } catch(e){console.log(e)}
  srv.close();
});
"

