const Joi=require('joi');
let schema = Joi.object({expectBody: Joi.alternatives().try(Joi.string().allow(''), Joi.object().instance(RegExp))});
console.log('empty string', schema.validate({expectBody:''}).error);
console.log('string', schema.validate({expectBody:'hello'}).error);
console.log('regex', schema.validate({expectBody:/abc/}).error);
console.log('no', schema.validate({}).error);
console.log('number', schema.validate({expectBody:123}).error?.message);
console.log('array', Joi.alternatives().try(Joi.string(), Joi.object().instance(RegExp)).validate(123).error?.message);
"

