const Joi=require('joi');
let s=Joi.object({expectBody: Joi.alternatives().try(Joi.string().allow(''), Joi.object().instance(RegExp))});
// test .unknown behavior
let s2=Joi.object({a:Joi.string()});
console.log(s2.validate({a:'hi', b:123}).error); // default allows unknown?
console.log(s2.validate({a:'hi', b:123}, {allowUnknown:true}).error);
